import std.concurrent as conc
import std.io

pub type AppError = Failed(String)

pub fn main() effect io -> Result<(), AppError> {
    let a: conc.Channel<Int64> = conc.channel(1)
    let b: conc.Channel<Int64> = conc.channel(1)
    a.send(1)
    let v = select {
        case x = a.receive() => 1
        case y = b.receive() => 2
    }
    if v == 1 {
        io.println("took-a")
    } else {
        io.println("took-b")
    }
    return Ok(())
}
